contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept any amount to forward into c; ensure this contract has enough balance.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Record the owner's address and this contract balance before the call
        address ownerBefore = c.owner();
        uint balanceBefore = address(this).balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: owner must still be a non-zero address (i.e., not 0x0)
        // and this test contract's balance must not have increased as a result of calling c.go.
        // (It may decrease by `amount` plus gas; it must not be larger than before.)
        assert(ownerBefore != address(0) && address(this).balance <= balanceBefore);
    }

    receive() external payable {}
}

